contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(address _vader, address _usdv, address _vault, address _proposedUtils) public {
        c.init(_vader, _usdv, _vault);
        c.newAddressProposal(_proposedUtils, "UTILS");
        uint pid = c.proposalCount();
        c.voteProposal(pid);
        c.finaliseProposal(pid);
        bool finalised = c.mapPID_finalised(pid);
        assert(_vader != address(0) ? finalised : !finalised);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _vader, address _usdv, address _vault, address _addr) public payable {
        require(_vader != address(0));
        c.init(_vader, _usdv, _vault);
        c.newAddressProposal(_addr, 'UTILS');
        uint pid = c.proposalCount();
        c.finaliseProposal(pid);
        bool reverted = false;
        assembly { reverted := iszero(eq(returndatasize(), 0x20)) }
        assert(reverted == false);
    }
}
